def _parse_work_hour_approval_status(value, *, default=None) -> tuple[str | None, bool]:
    explicit = value is not None and str(value).strip() != ""
    raw = str(value).strip().lower() if explicit else default
    if raw is None or raw == "all":
        return None, explicit
    if raw not in WORK_HOUR_APPROVAL_VALUES:
        raise HTTPException(status_code=400, detail="审批状态无效，应为 pending / approved / rejected / all")
    return raw, explicit

